import uuid

import citas.utils
from django.db import migrations, models


def corregir_codigos_cita_duplicados(apps, schema_editor):
    Cita = apps.get_model("citas", "Cita")

    codigos_usados = set()

    for cita in Cita.objects.order_by("id").iterator():
        codigo = cita.codigo_cita

        # Conserva la primera aparición del código.
        # Si está vacío o ya fue usado, genera uno nuevo.
        if not codigo or codigo in codigos_usados:
            while True:
                nuevo_codigo = f"DOC-{uuid.uuid4().hex[:8].upper()}"

                if (
                    nuevo_codigo not in codigos_usados
                    and not Cita.objects.filter(
                        codigo_cita=nuevo_codigo
                    ).exists()
                ):
                    break

            cita.codigo_cita = nuevo_codigo
            cita.save(update_fields=["codigo_cita"])
            codigo = nuevo_codigo

        codigos_usados.add(codigo)


